module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] S,
    input logic       Cout
);

    // The 5-bit output must equal A + B + Cin.
    check_full_sum_match: assert property (
        @(posedge clk)
        {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Bit 0 sum follows the first full-adder equation.
    check_sum_bit0_equation: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_sum_bit1_ripple: assert property (
        @(posedge clk)
        S[1] == (
            A[1] ^ B[1] ^
            ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
        )
    );

    // Bit 2 sum uses the carry generated by bits 0 and 1.
    check_sum_bit2_ripple: assert property (
        @(posedge clk)
        S[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (
                    ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
                    & (A[1] ^ B[1])
                )
            )
        )
    );

    // Bit 3 sum uses the carry generated by bits 0 through 2.
    check_sum_bit3_ripple: assert property (
        @(posedge clk)
        S[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (
                    (
                        (A[1] & B[1]) |
                        (
                            ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
                            & (A[1] ^ B[1])
                        )
                    )
                    & (A[2] ^ B[2])
                )
            )
        )
    );

    // Carry-out matches the final ripple-carry equation.
    check_cout_ripple: assert property (
        @(posedge clk)
        Cout == (
            (A[3] & B[3]) |
            (
                (
                    (A[2] & B[2]) |
                    (
                        (
                            (A[1] & B[1]) |
                            (
                                ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
                                & (A[1] ^ B[1])
                            )
                        )
                        & (A[2] ^ B[2])
                    )
                )
                & (A[3] ^ B[3])
            )
        )
    );

endmodule